traces.query:
PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Firewall_Edge ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?criticalAlarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "CRITICAL" .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?label WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice net:Router_Core ;
         rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT ?severity WHERE {
  net:Alarm_PacketDrop net:hasSeverity ?severity .
}

PREFIX net: <http://example.org/network#>
SELECT ?device (COUNT(?alarm) AS ?alarmCount)
WHERE {
  ?alarm a net:Alarm ;
         net:affectsDevice ?device .
}
GROUP BY ?device
ORDER BY DESC(?alarmCount)
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
}
ORDER BY ?time
LIMIT 1

PREFIX net: <http://example.org/network#>
SELECT ?mitreId WHERE {
  net:Incident_DDoS net:classifiedAs ?ap .
  ?ap net:mitreId ?mitreId .
}

PREFIX net: <http://example.org/network#>

SELECT ?deviceType
WHERE {
  net:Server_Web net:deviceType ?deviceType .
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(?alarm) AS ?alarmCount)
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
}

PREFIX net: <http://example.org/network#>
SELECT ?alarm
WHERE {
  ?alarm a net:Alarm ;
         net:hasSeverity "HIGH" .
}

PREFIX net: <http://example.org/network#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?alarm ?time
WHERE {
  ?alarm a net:Alarm ;
         net:triggeredAt ?time .
  FILTER ( ?time > "2026-06-02T14:01:00"^^xsd:dateTime )
}

PREFIX net: <http://example.org/network#>

SELECT DISTINCT ?rootAlarm
WHERE {
  net:Incident_DDoS net:composedOf ?alarm .
  ?alarm (net:causallyLinkedTo)* ?rootAlarm .
  FILTER NOT EXISTS { ?cause net:causallyLinkedTo ?rootAlarm . }
  ?rootAlarm a net:Alarm .
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?rootAlarm ?rootLabel WHERE {
  net:Alarm_WebTimeout net:causallyLinkedTo+ ?rootAlarm .
  OPTIONAL { ?rootAlarm rdfs:label ?rootLabel . }
  FILTER NOT EXISTS { ?intermediate net:causallyLinkedTo ?rootAlarm }
}

PREFIX net: <http://example.org/network#>
SELECT ?causeAlarm ?causeType WHERE {
  net:Alarm_Latency net:causallyLinkedTo ?causeAlarm .
  ?causeAlarm net:alarmType ?causeType .
}

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
SELECT (EXISTS {
  net:Alarm_CPU net:causallyLinkedTo+ net:Alarm_WebTimeout .
} AS ?cpuCausesWebTimeout) WHERE {}

PREFIX net: <http://example.org/network#>

ASK {
  <http://example.org/network#Alarm_Latency> net:causallyLinkedTo+ <http://example.org/network#Alarm_WebTimeout> .
}

PREFIX net: <http://example.org/network#>
SELECT ?rootAlarm ?device
WHERE {
  ?rootAlarm a net:Alarm .
  FILTER NOT EXISTS {
    ?prev net:causallyLinkedTo ?rootAlarm .
  }
  ?rootAlarm net:affectsDevice ?device .
}

PREFIX net: <http://example.org/network#>
SELECT ?direction WHERE {
  {
    net:Alarm_Latency net:causallyLinkedTo net:Alarm_PacketDrop .
    BIND("Latency causes PacketDrop" AS ?direction)
  }
  UNION
  {
    net:Alarm_PacketDrop net:causallyLinkedTo net:Alarm_Latency .
    BIND("PacketDrop causes Latency" AS ?direction)
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?alarm
WHERE {
  ?alarm net:correlatedWith net:Alarm_PacketDrop .
  FILTER NOT EXISTS { ?alarm net:causallyLinkedTo net:Alarm_PacketDrop }
  FILTER NOT EXISTS { net:Alarm_PacketDrop net:causallyLinkedTo ?alarm }
}

PREFIX net: <http://example.org/network#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?device ?deviceLabel WHERE {
  # Alarms that are part of the DDoS incident
  net:Incident_DDoS net:composedOf ?alarm .

  # Root cause alarms: no other alarm causes them
  FILTER NOT EXISTS {
    ?cause net:causallyLinkedTo ?alarm .
  }

  # Device affected by the root alarm
  ?alarm net:affectsDevice ?device .
  OPTIONAL { ?device rdfs:label ?deviceLabel . }
}

PREFIX net: <http://example.org/network#>
SELECT ?downstreamAlarm ?label WHERE {
  net:Alarm_FirewallSpike net:causallyLinkedTo+ ?downstreamAlarm .
  ?downstreamAlarm rdfs:label ?label .
}

PREFIX net: <http://example.org/network#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?downstreamAlarm ?label
WHERE {
  <http://example.org/network#Alarm_CPU> net:causallyLinkedTo ?downstreamAlarm .
  OPTIONAL { ?downstreamAlarm rdfs:label ?label . }
}

PREFIX net: <http://example.org/network#>
SELECT (COUNT(DISTINCT ?downstream) AS ?preventedAlarms) WHERE {
  net:Alarm_PacketDrop net:causallyLinkedTo+ ?downstream .
}

PREFIX net: <http://example.org/network#>

SELECT ?remainingAlarm ?remainingAlarmLabel WHERE {
  # Get the incident
  ?incident a net:Incident ;
            net:composedOf ?alarm .
  # Get label of each alarm
  ?alarm rdfs:label ?remainingAlarmLabel .
  BIND(?alarm AS ?remainingAlarm)

  # Identify the CPU overload alarm
  BIND(net:Alarm_CPU AS ?cpuAlarm)

  # Exclude alarms that are downstream of the CPU alarm
  FILTER NOT EXISTS {
    ?cpuAlarm net:causallyLinkedTo+ ?alarm .
  }
}

PREFIX net: <http://example.org/network#>

SELECT ?downstream
WHERE {
  net:Alarm_Latency (net:causallyLinkedTo)+ ?downstream .
  FILTER(?downstream = net:Alarm_WebTimeout)
}
